/**
 * Shared JSON helpers for the route handlers.
 *
 * Owner D. Every handler under `src/app/api` returns the same envelope as the
 * Server Actions — `{ error: AppErrorShape }` on failure — so a client can use
 * one parser for both. The status code comes from `HTTP_STATUS_BY_CODE`, which
 * is the single mapping from domain error code to HTTP.
 */

import { HTTP_STATUS_BY_CODE, toAppError } from "@/lib/errors";
import type { AppErrorShape, ApiErrorBody } from "@/types/api";

/** Turns any thrown value into the JSON error envelope with the right status. */
export function errorResponse(error: unknown): Response {
  const shape: AppErrorShape = toAppError(error);
  const body: ApiErrorBody = { error: shape };
  return Response.json(body, { status: HTTP_STATUS_BY_CODE[shape.code] });
}

/** Builds the envelope for a failure the handler detected itself. */
export function failure(
  code: AppErrorShape["code"],
  message: string,
): Response {
  const body: ApiErrorBody = { error: { code, message } };
  return Response.json(body, { status: HTTP_STATUS_BY_CODE[code] });
}

/**
 * Cron endpoints are protected by a shared secret rather than a session — they
 * are called by the platform scheduler, which has no cookie jar.
 */
export function assertCronSecret(request: Request): void {
  const expected = process.env.TASKFLOW_CRON_SECRET;
  if (expected === undefined || expected.length === 0) {
    // No secret configured means cron is disabled rather than wide open.
    throw new CronAuthError("Cron trigger is not configured.");
  }
  if (request.headers.get("x-taskflow-cron") !== expected) {
    throw new CronAuthError("Bad cron secret.");
  }
}

export class CronAuthError extends Error {
  readonly code = "unauthorized" as const;

  constructor(message: string) {
    super(message);
    this.name = "CronAuthError";
  }
}
/**
 * Maps thrown domain errors onto `AppErrorShape`.
 *
 * The service layer throws (`PermissionDeniedError`, `TenantScopeError`,
 * `FeatureDisabledError`, `AlreadyArchivedError`, `InvalidSlugError`,
 * `ZodError`); Server Actions and Route Handlers never propagate those to the
 * client. Everything funnels through `toAppError()` so one thrown class maps
 * to exactly one `ErrorCode` and one HTTP status, app-wide.
 */
import { FeatureDisabledError } from "@/lib/feature-flags";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import type { ActionResult, AppErrorShape, ErrorCode } from "@/types/api";
import { ZodError, type ZodIssue } from "zod";

export const HTTP_STATUS_BY_CODE: Readonly<Record<ErrorCode, number>> = {
  unauthorized: 401,
  forbidden: 403,
  not_found: 404,
  validation_failed: 422,
  conflict: 409,
  rate_limited: 429,
  plan_limit_exceeded: 402,
  tenant_scope_violation: 403,
  internal_error: 500,
};

/** True for the error classes this module knows how to translate faithfully. */
export function isDomainError(error: unknown): boolean {
  return (
    error instanceof PermissionDeniedError ||
    error instanceof TenantScopeError ||
    error instanceof FeatureDisabledError ||
    error instanceof AlreadyArchivedError ||
    error instanceof InvalidSlugError ||
    error instanceof ZodError
  );
}

/** Collapses a `ZodError` into the `field → messages` map forms consume. */
export function fieldErrorsFromZod(
  error: ZodError,
): Readonly<Record<string, readonly string[]>> {
  const fields: Record<string, string[]> = {};
  for (const issue of error.issues as readonly ZodIssue[]) {
    const key = issue.path.length === 0 ? "_root" : issue.path.join(".");
    (fields[key] ??= []).push(issue.message);
  }
  return fields;
}

export function toAppError(error: unknown): AppErrorShape {
  if (error instanceof ZodError) {
    return {
      code: "validation_failed",
      message: "Please correct the highlighted fields.",
      fieldErrors: fieldErrorsFromZod(error),
    };
  }

  if (error instanceof PermissionDeniedError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: {
        action: error.action,
        resourceKind: error.decision.resourceKind,
        reason: error.decision.reason,
      },
    };
  }

  if (error instanceof TenantScopeError) {
    return {
      code: "tenant_scope_violation",
      message: "That resource belongs to a different organization.",
      meta: { expectedOrgId: error.expectedOrgId, actualOrgId: error.actualOrgId },
    };
  }

  if (error instanceof FeatureDisabledError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: { flag: error.flag },
    };
  }

  if (error instanceof AlreadyArchivedError) {
    return {
      code: "conflict",
      message: error.message,
      meta: { entity: error.entity, id: error.id },
    };
  }

  if (error instanceof InvalidSlugError) {
    return {
      code: "validation_failed",
      message: error.message,
      fieldErrors: { slug: [error.message] },
      meta: { value: error.value },
    };
  }

  return {
    code: "internal_error",
    message:
      error instanceof Error ? error.message : "Something went wrong. Try again.",
  };
}

/** The failure envelope a Server Action returns instead of throwing. */
export function toActionResult(error: unknown): ActionResult<never> {
  return {
    ok: false,
    error: toAppError(error),
    submittedAt: new Date().toISOString(),
  };
}

/** Domain-error to `AppErrorShape` mapping for every error class. */
import { describe, expect, it } from "vitest";
import { z } from "zod";
import {
  HTTP_STATUS_BY_CODE,
  fieldErrorsFromZod,
  isDomainError,
  toActionResult,
  toAppError,
} from "@/lib/errors";
import { FeatureDisabledError } from "@/lib/feature-flags";
import { PermissionDeniedError, explain } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import type { OrgId } from "@/types/common";
import { makeActor, ORG_A, ORG_B } from "../helpers/factories";

const schema = z.object({
  title: z.string().min(3),
  estimate: z.number().int(),
});

function permissionError(): PermissionDeniedError {
  const actor = makeActor({ role: "viewer" });
  const resource = { kind: "organization", orgId: ORG_A } as const;
  return new PermissionDeniedError("org:delete", explain(actor, "org:delete", resource));
}

describe("lib/errors", () => {
  it("maps a permission denial to `forbidden` with the decision in meta", () => {
    const shape = toAppError(permissionError());
    expect(shape.code).toBe("forbidden");
    expect(shape.meta?.action).toBe("org:delete");
    expect(shape.meta?.reason).toBe("denied_by_role");
  });

  it("maps a tenant scope violation to `tenant_scope_violation`", () => {
    const shape = toAppError(new TenantScopeError(ORG_A, ORG_B));
    expect(shape.code).toBe("tenant_scope_violation");
    expect(shape.meta?.expectedOrgId).toBe(ORG_A);
    expect(shape.message).not.toContain(ORG_B as string);
  });

  it("maps a disabled feature to `forbidden` and names the flag", () => {
    const shape = toAppError(new FeatureDisabledError("webhooks"));
    expect(shape.code).toBe("forbidden");
    expect(shape.meta?.flag).toBe("webhooks");
  });

  it("maps double archiving to `conflict`", () => {
    const shape = toAppError(new AlreadyArchivedError("Issue", "01ISS"));
    expect(shape.code).toBe("conflict");
    expect(shape.meta?.entity).toBe("Issue");
  });

  it("maps an invalid slug to `validation_failed` with a slug field error", () => {
    const shape = toAppError(new InvalidSlugError("Admin!", "is reserved"));
    expect(shape.code).toBe("validation_failed");
    expect(shape.fieldErrors?.slug?.[0]).toContain("is reserved");
  });

  it("maps a ZodError to field errors keyed by dotted path", () => {
    const parsed = schema.safeParse({ title: "no", estimate: 1.5 });
    expect(parsed.success).toBe(false);
    if (parsed.success) return;

    const fields = fieldErrorsFromZod(parsed.error);
    expect(Object.keys(fields).sort()).toEqual(["estimate", "title"]);
    expect(toAppError(parsed.error).code).toBe("validation_failed");
  });

  it("falls back to `internal_error` for an unknown throw", () => {
    expect(toAppError(new Error("boom")).code).toBe("internal_error");
    expect(toAppError("boom").code).toBe("internal_error");
    expect(toAppError("boom").message).toContain("Something went wrong");
  });

  it("recognises exactly the domain error classes", () => {
    expect(isDomainError(permissionError())).toBe(true);
    expect(isDomainError(new TenantScopeError(ORG_A, ORG_B))).toBe(true);
    expect(isDomainError(new InvalidSlugError("x", "too short"))).toBe(true);
    expect(isDomainError(new Error("boom"))).toBe(false);
    expect(isDomainError(null)).toBe(false);
  });

  it("gives every error code an HTTP status", () => {
    for (const [code, status] of Object.entries(HTTP_STATUS_BY_CODE)) {
      expect(status, code).toBeGreaterThanOrEqual(400);
    }
    expect(HTTP_STATUS_BY_CODE.rate_limited).toBe(429);
    expect(HTTP_STATUS_BY_CODE.plan_limit_exceeded).toBe(402);
  });

  it("wraps a failure as an ActionResult, never throwing", () => {
    const result = toActionResult(new AlreadyArchivedError("Project", "01PRJ"));
    expect(result.ok).toBe(false);
    if (result.ok) return;
    expect(result.error.code).toBe("conflict");
    expect(typeof result.submittedAt).toBe("string");
  });

  it("keeps a cross-tenant org id out of the user-facing message", () => {
    const other = "01HZZZDDDDDDDDDDDDDDDDDDDD" as OrgId;
    expect(toAppError(new TenantScopeError(ORG_A, other)).message).toBe(
      "That resource belongs to a different organization.",
    );
  });
});

